class HospitalSystem {
    private String patientName;
    private String doctorId;
    private String diagnosis;
    private String appointmentDate;

    public HospitalSystem(String patientName, String doctorId,
                           String diagnosis, String appointmentDate) {
        this.patientName = patientName;
        this.doctorId = doctorId;
        this.diagnosis = diagnosis;
        this.appointmentDate = appointmentDate;
    }

    public boolean checkDoctorAvailability() {
        // Fetch doctor schedule, check existing appointments
        System.out.println("Checking availability for doctor: " + doctorId);
        return true;
    }

    public void maintainPatientRecords() {
        // Store diagnosis history, update prescriptions, archive past visits
        System.out.println("Saving medical record for: " + patientName + " (" + diagnosis + ")");
    }

    public double calculateBilling() {
        double consultationFee = 100.0;
        double insuranceDiscount = 0.20 * consultationFee;
        double finalAmount = consultationFee - insuranceDiscount;
        System.out.println("Total bill for " + patientName + ": $" + finalAmount);
        return finalAmount;
    }

    public void dispatchAmbulance() {
        // Detect emergency flag, find nearest available unit, send location to driver
        System.out.println("Emergency detected for: " + patientName);
        System.out.println("Dispatching nearest ambulance to location...");
    }
}

public class Main {
    public static void main(String[] args) {
        HospitalSystem system = new HospitalSystem("John Doe", "DOC-101", "Fracture", "2026-07-25");
        system.checkDoctorAvailability();
        system.maintainPatientRecords();
        system.calculateBilling();
        system.dispatchAmbulance();
    }
}

