import java.util.Date;

class AppointmentScheduler {
    public boolean checkAvailability(String doctorId, Date date) {
        if (date.before(new Date())) {
            throw new IllegalArgumentException("Cannot book a past date");
        }
        // Fetch doctor schedule and verify slot
        System.out.println("Checking availability for doctor: " + doctorId);
        return true; // Simplified for illustration
    }
}

public class Main {
    public static void main(String[] args) {
        AppointmentScheduler scheduler = new AppointmentScheduler();
        Date future = new Date(System.currentTimeMillis() + 86400000L);
        boolean available = scheduler.checkAvailability("DOC-101", future);
        System.out.println("Available: " + available);
    }
}

