#include <iostream>
#include <string>
#include <chrono>
#include <stdexcept>

class AppointmentScheduler {
public:
    bool checkAvailability(const std::string& doctorId,
                            std::chrono::system_clock::time_point date) {
        if (date < std::chrono::system_clock::now()) {
            throw std::invalid_argument("Cannot book a past date");
        }
        std::cout << "Checking availability for doctor: " << doctorId << std::endl;
        return true; // Simplified for illustration
    }
};

int main() {
    AppointmentScheduler scheduler;
    auto future = std::chrono::system_clock::now() + std::chrono::hours(24);
    bool available = scheduler.checkAvailability("DOC-101", future);
    std::cout << "Available: " << std::boolalpha << available << std::endl;
    return 0;
}

